(function ($) {
upfrontrjs.define('scripts/upfront/inline-panels/control',[
	'scripts/upfront/inline-panels/item'
], function (Item) {
	var Control = Item.extend({
		events: {
			'click': 'clicked'
		},

		initialize: function(options) {
			this.options = options || {};
			this.label = this.options.label;
			this.icon = this.options.icon;
		},

		clicked: function(e){
			var target = $(e.target);

			e.preventDefault();
			e.stopPropagation();
			this.$el
				.siblings('.upfront-inline-panel-subitem-active')
				.removeClass('upfront-inline-panel-subitem-active');

			if(!target.hasClass('upfront-icon-region-settings')){			
				if(!target.closest('.upfront-inline-panel-item').hasClass('upfront-control-dialog-open'))	target.closest('.upfront-wrapper').addClass('upfront-inline-panel-item-open');
				else	target.closest('.upfront-wrapper').removeClass('upfront-inline-panel-item-open');
			}

			this.trigger('click', e);
		},

		setIsSelected: function(isSelected) {
			if (isSelected) {
				this.$el.addClass('inline-panel-item-selected');
				return;
			}

			this.$el.removeClass('inline-panel-item-selected');
		}
	});

	return Control;
});
})(jQuery);

(function ($) {
upfrontrjs.define('scripts/upfront/inline-panels/multi-control',[
	'scripts/upfront/inline-panels/item-multi'
], function (ItemMulti) {
	var MultiControl = ItemMulti.extend({
	events: {
		'click': 'clicked',
		'click .upfront-inline-panel-item': 'selectItem'
	},
	render: function(){
		ItemMulti.prototype.render.call(this, arguments);
	},
	clicked: function(e){
		var $subitem = this.$el.children('.upfront-inline-panel-subitem');
		if ( $(e.target).closest($subitem).length > 0 )
			return;
		this.trigger('click', e);
		this.toggle_subitem();
	},
	get_selected_item: function () {
		return this.selected;
	},
	selectItem: function(e){
		var found = false,
			target = $(e.target).is('i') ? $(e.target) : $(e.target).find('i')
		;
		_.each(this.sub_items, function(item, key){
			if(target.hasClass('upfront-icon-region-' + item.icon)) {
				found = key;
			}
		});

		if(found){
			this.selected = found;
			this.render();
			this.trigger('select', found);
		}
	}

	});

	return MultiControl;
});
})(jQuery);

(function ($) {
upfrontrjs.define('scripts/upfront/inline-panels/tooltip-control',[
	'scripts/upfront/inline-panels/item',
	'scripts/upfront/inline-panels/control'
], function (Item, Control) {
	var l10n = Upfront.mainData.l10n.image_element;

	var TooltipControl = Control.extend({
		multiControl: true,

		events: {
			'click': 'onClickControl',
			'click .upfront-inline-panel-item': 'selectItem'
		},

		initialize: function() {
			var me = this;
			$(document).on("click", function(e) {
				var	target = $(e.target);

				if(target.closest('#page').length && target[0] !== me.el && !target.closest(me.el).length && me.isOpen) {
					me.close();
				}
			});
		},

		onClickControl: function(e){
			if (this.isDisabled) {
				return;
			}

			e.preventDefault();

			this.clicked(e);

			this.$el.siblings('.upfront-control-dialog-open').removeClass('upfront-control-dialog-open');

			if (this.isOpen) {
				this.close();
			} else {
				this.open();
			}
		},

		open: function() {
			this.isOpen = true;
			this.$el.addClass('upfront-control-dialog-open');
			this.trigger('panel:open');
			this.hideParentItems();
			this.updateWidth();
		},

		close: function() {
			this.isOpen = false;
			this.$el.removeClass('upfront-control-dialog-open');
			this.trigger('panel:close');
			this.showParentItems();
			
			var parentItems = this.$el.closest('.image-sub-control').children('.upfront-inline-panel-item');
			
			this.$el
				.closest('.image-sub-control').css('width', (28 * parentItems.length) + 2);
		},
		
		hideParentItems: function() {
			this.$el.parent().closest('.image-sub-control')
				.find('.upfront-inline-panel-item')
				.not('.uimage-caption-control-item, .uimage-caption-control-item .upfront-inline-panel-item')
				.hide();
		},
		
		showParentItems: function() {
			this.$el.parent().closest('.image-sub-control')
				.find('.upfront-inline-panel-item')
				.not('.uimage-caption-control-item, .uimage-caption-control-item .upfront-inline-panel-item')
				.show();
		},

		render: function() {
			Item.prototype.render.call(this, arguments);
			var captionControl = this.$('.uimage-caption-control'),
				me = this,
				selectedItem,
				wrapperClass = ''
			;
			
			this.item_count = 0;

			if(!this.$el.hasClass('uimage-caption-control-item')) {
				this.$el.addClass('uimage-caption-control-item');
			}

			if(typeof this.wrapperClass !== "undefined") {
				wrapperClass = this.wrapperClass;
			}

			if(!captionControl.length){
				captionControl = $('<div class="uimage-caption-control inline-panel-control-dialog '+ wrapperClass +'"></div>');
				this.$el.append(captionControl);
			}
			_.each(this.sub_items, function(item, key){
				if(key === me.selected){
					item.setIsSelected(true);
				} else {
					item.setIsSelected(false);
				}
				item.render();
				item.$el.find('i').addClass('upfront-icon-region-caption');
				captionControl.append(item.$el);
				me.listenTo(item, 'click', me.selectItem);
				me.item_count++;
			});

			selectedItem = this.sub_items[this.selected];
			if(selectedItem){
				if( typeof selectedItem.icon !== 'undefined' ){
					this.$el.children('i').addClass('upfront-icon-region-' + selectedItem.icon);
				} else if( typeof selectedItem.label !== 'undefined' ){
					this.$el.find('.tooltip-content').append( ': ' +  selectedItem.label );
				}
			}
		},

		get_selected_item: function () {
			return this.selected;
		},

		selectItem: function(e){
			var found = false,
				target = $(e.target).is('i') ? $(e.target) : $(e.target).find('i');

			_.each(this.sub_items, function(item, key){
				if(target.hasClass('upfront-icon-region-' + item.icon)) {
					found = key;
				}

				if( !found && $(e.target).closest('.upfront-inline-panel-item').attr('id') === item.id ){
					found = key;
				}

			});
			
			if(found === "back") {
				this.close();
				return;
			}

			if(found) {
				this.selected = found;
				this.render();
				this.trigger('select', found);
			}
		},
		
		updateWidth: function () {
			//Set width depending of items
			this.$el
				.closest('.image-sub-control').css('width', (28 * this.item_count) + 2);
				
			this.$el
				.find('.uimage-caption-control').css('width', (28 * this.item_count) + 2);
		},

		setDisabled: function(isDisabled) {
			this.isDisabled = isDisabled;
			if (isDisabled) {
				this.tooltip = l10n.ctrl.caption_position_disabled;
			} else {
				this.tooltip = l10n.ctrl.caption_display;
			}
		}
	});

	return TooltipControl;
});
})(jQuery);

(function ($) {
upfrontrjs.define('scripts/upfront/inline-panels/sub-control',[
	'scripts/upfront/inline-panels/item',
	'scripts/upfront/inline-panels/control'
], function (Item, Control) {
	var l10n = Upfront.mainData.l10n.image_element;

	var SubControl = Control.extend({
		multiControl: true,

		events: {
			'click': 'onClickControl',
			'click .upfront-inline-panel-item': 'selectItem'
		},

		initialize: function() {
			var me = this;
			$(document).on("click", function(e) {
				var	target = $(e.target);

				if(target.closest('#page').length && target[0] !== me.el && !target.closest(me.el).length && me.isOpen) {
					me.close();
				}
			});
			
			this.listenTo(Upfront.Events, "upfront:hide:subControl", this.close);
		},

		onClickControl: function(e){
			if (this.isDisabled) {
				return;
			}

			e.preventDefault();

			this.clicked(e);

			this.$el.siblings('.upfront-sub-control-dialog-open').removeClass('upfront-sub-control-dialog-open');

			if (this.isOpen) {
				this.close();
			} else {
				// We have to close all open panels before open this one
				Upfront.Events.trigger('upfront:hide:subControl');

				this.open();
			}
		},

		open: function() {
			this.isOpen = true;
			this.$el.addClass('upfront-sub-control-dialog-open');
			Upfront.Events.trigger('upfront:hide:paddingPanel');
			this.trigger('panel:open');
			
			var parent = this.$el.closest('.upfront-inline-panel');
			
			if(this.inline === true) {
				parent.removeClass('upfront-panels-shadow');
			}
			
			this.updateWidth();
		},

		close: function() {
			this.isOpen = false;
			this.$el.removeClass('upfront-sub-control-dialog-open');
			this.trigger('panel:close');
			
			var parent = this.$el.closest('.upfront-inline-panel');
			
			if(this.inline === true) {
				if(!parent.hasClass('upfront-panels-shadow')) {
					parent.addClass('upfront-panels-shadow');
				}
			}
		},

		render: function() {
			Item.prototype.render.call(this, arguments);
			var captionControl = this.$('.image-sub-control'),
				me = this,
				selectedItem
			;
			
			this.item_count = 0;

			if(!captionControl.length){
				if(this.inline === true) {
					captionControl = $('<div class="image-sub-control upfront-panels-shadow inline-panel-sub-control-no-dropdown inline-panel-sub-control-dialog"></div>');
				} else {
					captionControl = $('<div class="image-sub-control upfront-panels-shadow inline-panel-sub-control-dialog"></div>');
				}
				this.$el.append(captionControl);
			}
			_.each(this.sub_items, function(item, key){
				if(key === me.selected){
					item.setIsSelected(true);
				} else {
					item.setIsSelected(false);
				}
				
				if(me.inline === true) {
					item.panel_type = 'tooltip';
				}
				
				item.render();
				item.delegateEvents();
				captionControl.append(item.$el);
				me.item_count++;
			});

			// Prepend arrow, it is not set like pseudo element because we cant update its styles with jQuery
			var panelArrow = '<span class="upfront-control-arrow"></span>';
			this.$el
				.find('.image-sub-control').prepend(panelArrow);
		},
		
		updateWidth: function () {
			//Set width depending of items
			this.$el
				.find('.image-sub-control').css('width', (28 * this.item_count) + 2);

			//Show sub controls on each open
			this.$el
				.find('.upfront-inline-panel-item').show();
		},

		get_selected_item: function () {
			return this.selected;
		},

		setDisabled: function(isDisabled) {
			this.isDisabled = isDisabled;
			if (isDisabled) {
				this.tooltip = l10n.ctrl.caption_position_disabled;
			} else {
				this.tooltip = l10n.ctrl.caption_display;
			}
		}
	});

	return SubControl;
});
})(jQuery);

