                    this.$editor.removeClass('redactor-editor redactor-linebreaks redactor-placeholder');
                    this.$editor.removeAttr('contenteditable');

                    var html = this.code.get();

                    // dropdowns off
                    this.$toolbar.find('a').each(function()
                    {
                        var $el = $(this);
                        if ($el.data('dropdown'))
                        {
                            $el.data('dropdown').remove();
                            $el.data('dropdown', {});
                        }
                    });


