		keyMove: function(e) {
			switch(e.which){
				case 40: //down
					this.maskOffset.top--;
					this.positionEditorElements();
					break;
				case 39: //right
					this.maskOffset.left--;
					this.positionEditorElements();
					break;
				case 37: //left
					this.maskOffset.left++;
					this.positionEditorElements();
					break;
				case 38: //up
					this.maskOffset.top++;
					this.positionEditorElements();
			}
		},

		fixImageTop: function(offset){
			if(offset && typeof offset.top !== 'undefined'){
				if(offset.top < 120){
					var margin = $('body').css('marginTop');
					margin = parseInt(margin.replace('px', ''), 10);
					if(!isNaN(margin)){
						this.fixTop = 120 - offset.top;
						$('body').css(('marginTop'), margin + this.fixTop);
						return this.fixTop;
					}
				}
			}
			return 0;
		},

		unfixImageTop: function(){
			if(this.fixTop){
				var margin = $('body').css('marginTop');
				margin = parseInt(margin.replace('px', ''), 10);
				if(!isNaN(margin)){
					$('body').css(('marginTop'), margin - this.fixTop);
				}
				this.fixTop = 0;
			}
		}
