upfrontrjs.define('elements/upfront-tabs/js/settings',[
	'scripts/upfront/element-settings/settings',
	'scripts/upfront/preset-settings/util',
	'text!elements/upfront-tabs/tpl/preset-style.html'
], function(ElementSettings, Util, styleTpl) {
	var l10n = Upfront.Settings.l10n.utabs_element;

	var TabsSettings = ElementSettings.extend({
		panels: {
			Appearance: {
				mainDataCollection: 'tabPresets',
				styleElementPrefix: 'tab-preset',
				ajaxActionSlug: 'tab',
				panelTitle: l10n.settings,
				presetDefaults: Upfront.mainData.presetDefaults.tab,
				styleTpl: styleTpl,
				stateModules: {
					Global: [
						{
							moduleType: 'Colors',
							options: {
								title: l10n.content_area_colors_label,
								multiple: false,
								single: true,
								abccolors: [
									{
										name: 'global-content-bg',
										label: l10n.content_area_bg_label
									}
								]
							}
						},
						{
							moduleType: 'Border',
							options: {
								state: 'static',
								title: '',
								fields: {
									use: 'global-useborder',
									width: 'global-borderwidth',
									type: 'global-bordertype',
									color: 'global-bordercolor'
								}
							}
						}
					],
					Static: [
						{
							moduleType: 'Colors',
							options: {
								title: l10n.colors_label,
								multiple: false,
								single: true,
								abccolors: [
									{
										name: 'static-tab-bg',
										label: l10n.tab_bg_label
									}
								]
							}
						},
						{
							moduleType: 'Typography',
							options: {
								title: l10n.tab_typography_label,
								state: 'static',
								toggle: false,
								fields: {
									typeface: 'static-font-family',
									fontstyle: 'static-font-style',
									weight: 'static-weight',
									style: 'static-style',
									size: 'static-font-size',
									line_height: 'static-line-height',
									color: 'static-font-color'
								}
							}
						},
						{
							moduleType: 'Border',
							options: {
								state: 'static',
								title: '',
								fields: {
									use: 'static-useborder',
									width: 'static-borderwidth',
									type: 'static-bordertype',
									color: 'static-bordercolor'
								}
							}
						}
					],

					Hover: [
						{
							moduleType: 'Colors',
							options: {
								title: l10n.colors_label,
								multiple: false,
								single: true,
								toggle: true,
								prepend: 'hover-',
								prefix: 'static',
								fields: {
									use: 'hover-use-color'
								},
								abccolors: [
									{
										name: 'hover-tab-bg',
										label: l10n.tab_bg_label
									}
								]
							}
						},
						{
							moduleType: 'Typography',
							options: {
								title: l10n.tab_typography_label,
								state: 'hover',
								toggle: true,
								prepend: 'hover-',
								prefix: 'static',
								fields: {
									use: 'hover-use-typography',
									typeface: 'hover-font-family',
									fontstyle: 'hover-font-style',
									weight: 'hover-weight',
									style: 'hover-style',
									size: 'hover-font-size',
									line_height: 'hover-line-height',
									color: 'hover-font-color'
								}
							}
						},
						{
							moduleType: 'Border',
							options: {
								state: 'hover',
								title: '',
								prepend: 'hover-',
								prefix: 'static',
								fields: {
									use: 'hover-useborder',
									width: 'hover-borderwidth',
									type: 'hover-bordertype',
									color: 'hover-bordercolor'
								}
							}
						},
						{
							moduleType: 'HovAnimation',
							options: {
								state: 'hover',
								title: '',
								toggle: true,
								fields: {
									use: 'hover-use-transition',
									duration: 'hover-transition-duration',
									easing: 'hover-transition-easing'
								}
							}
						}
					],

					Active: [
						{
							moduleType: 'Colors',
							options: {
								title: l10n.colors_label,
								multiple: false,
								single: true,
								toggle: true,
								prepend: 'active-',
								prefix: 'static',
								fields: {
									use: 'active-use-color'
							},
							abccolors: [
							{
								name: 'active-tab-bg',
								label: l10n.tab_bg_label
							}
						]
					}
				},
						{
							moduleType: 'Typography',
							options: {
								title: l10n.tab_typography_label,
								state: 'active',
								toggle: true,
								prepend: 'active-',
								prefix: 'static',
								fields: {
									use: 'active-use-typography',
									typeface: 'active-font-family',
									fontstyle: 'active-font-style',
									weight: 'active-weight',
									style: 'active-style',
									size: 'active-font-size',
									line_height: 'active-line-height',
									color: 'active-font-color'
								}
							}
						},
						{
							moduleType: 'Border',
							options: {
								state: 'active',
								title: '',
								prepend: 'active-',
								prefix: 'static',
								fields: {
									use: 'active-useborder',
									width: 'active-borderwidth',
									type: 'active-bordertype',
									color: 'active-bordercolor'
								}
							}
						}
					]
				},

				migrateElementStyle: function(styles, selector) {
					//replace tab container which is one line with preset
					styles = styles.replace(/\.upfront-tabs-container/g, '.tabs-wrapper');

					return styles;
				},

				migrateDefaultStyle: function(styles) {
					//replace image wrapper class
					styles = styles.replace(/(div)?\.upfront-tabs\s/g, '');
					styles = styles.replace(/(div)?\.upfront-object\s/g, '');

					return styles;
				},

				migratePresetProperties: function(newPreset) {

					var preset = this.property('preset') ? this.clear_preset_name(this.property('preset')) : 'default',
						props = this.presets.findWhere({id: preset}),
						obj = {};

					if(typeof props !== "undefined") {
						_.each(props.attributes, function(preset_value, index) {

							if(index === 'id' || index === 'name' || index === 'preset_style' || index === 'legacy') {
								return;
							}

							obj[index] = preset_value;
						});
					}

					//Migrate properties from existing preset
					newPreset.set(obj);


					newPreset.set({
						'active-tab-bg': 'rgba(255,255,255, 0)',
						'static-tab-bg': 'rgba(255,255,255, 0)',
						'hover-tab-bg': 'rgba(255,255,255, 0)',
						'static-useborder': '',
						'hover-useborder': '',
						'active-useborder': '',
						'global-content-bg': 'rgba(255,255,255, 0)',
						'global-useborder': ''
					});
				}
			}
		},
		title: l10n.settings
	});

	// Generate presets styles to page
	Util.generatePresetsToPage('tab', styleTpl);

	return TabsSettings;
});


upfrontrjs.define('text!elements/upfront-tabs/tpl/utabs.html',[],function () { return '<div class="upfront-tabs-container tab-preset-<?php echo $preset ?>">\r\n  <div class="tabs-wrapper" role="tablist">\r\n    <div class="tabs-menu-wrapper">\r\n      <div class="tabs-menu">\r\n        <?php for ($i = 0; $i < $tabs_count; $i++) { ?>\r\n        <div class="tabs-tab  <?php if($i === 0) { ?>tabs-tab-active<?php } ?>" data-content-id="<?php echo $element_id ?>-<?php echo $i ?>" aria-controls="panel-<?php echo $i ?>" role="tab" tabindex="0">\r\n          <div class="inner-box">\r\n            <?php echo $tabs[$i][\'title\'] ?>\r\n          </div>\r\n          <?php if (!empty($show_remove)) { ?>\r\n          <i></i>\r\n          <?php } ?>\r\n        </div>\r\n        <?php } ?>\r\n      </div>\r\n    </div>\r\n    <div class="utabs-content">\r\n      <?php for ($i = 0; $i < $tabs_count; $i++) { ?>\r\n      <div id="<?php echo $element_id ?>-<?php echo $i ?>" class="utab-content <?php if($i === 0) { ?>utab-content-active<?php } ?>" role="tabpanel"><?php echo $tabs[$i][\'content\'] ?></div>\r\n      <?php } ?>\r\n    </div>\r\n  </div>\r\n</div>\r\n';});

(function ($) {
upfrontrjs.define('utabs',[
	'elements/upfront-tabs/js/model',
	'elements/upfront-tabs/js/element',
	'elements/upfront-tabs/js/settings',
	'scripts/upfront/preset-settings/util',
	'text!elements/upfront-tabs/tpl/utabs.html',
	'text!elements/upfront-tabs/tpl/preset-style.html'
], function(UtabsModel, TabsElement, TabsSettings, PresetUtil, tabsTpl, settingsStyleTpl) {
	var l10n = Upfront.Settings.l10n.utabs_element;

	// Kill live site tab handling
	$('body').off('touchstart click', '.tabs-tab');

	var UtabsView = Upfront.Views.ObjectView.extend({
		model: UtabsModel,
		currentTabId: false,
		tabsTpl: Upfront.Util.template(tabsTpl),
		elementSize: {width: 0, height: 0},

		initialize: function(){
			if(! (this.model instanceof UtabsModel)){
				this.model = new UtabsModel({properties: this.model.get('properties')});
			}

			// Setup default tab titles, ditch placeholder stuff
			var tabs = this.property('tabs');
			_.each(tabs, function(tab, index) {
				if (tab.title.trim() === '') {
					tabs[index].title = l10n.tab_label + ' ' + (index + 1);
				}
			});
			this.property('tabs', tabs);

			this.events = _.extend({}, this.events, {
				// 'click .add-item': 'addTab',
				'click .tabs-tab': 'onTabClick',
				'keydown .tabs-tab[contenteditable=true]': 'onTabKeydown',
				'click .utab-content-active': 'onContentClick',
				'click i': 'deleteTab',
				'dblclick .utab-content:not(.redactor-editor)': 'startContentEditor'
			});
			this.delegateEvents();

			this.model.get('properties').on('change', this.render, this);
			this.model.get('properties').on('change', this.handle_visual_padding_hint, this);
			this.model.get('properties').on('add', this.render, this);
			this.model.get('properties').on('remove', this.render, this);

			this.listenTo(Upfront.Events, "theme_colors:update", this.update_colors, this);

			// Check if preset exist, if not replace with default
			this.check_if_preset_exist();
		},

		update_colors: function () {
			var me = this,
				preset = this.model.get_property_value_by_name("preset"),
				props = PresetUtil.getPresetProperties('tab', preset) || {}
			;

			if (Object.keys(props).length <= 0) return false; // No properties, carry on

			PresetUtil.updatePresetStyle('tab', props, settingsStyleTpl);

		},

		onContentClick: function() {
			this.$el.find('.tabs-tab-active .inner-box').trigger('blur');
		},

		addTab: function(e) {
			e.preventDefault();
			this.property('tabs').push({
				title: l10n.tab_label + ' ' + (1 + this.property('tabs_count')),
				content: l10n.content_label + ' ' + (1 + this.property('tabs_count'))
			});
			this.property('tabs_count', this.property('tabs').length, false);
			this.render();
		},

		deleteTab: function(event) {
			if (!Upfront.Application.user_can_modify_layout()) return false;

			var element = $(event.currentTarget);
			var tab = element.parents('.tabs-tab');
			var id = $(tab).data('content-id').split('-').pop();
			this.property('tabs').splice(id, 1);
			this.property('tabs_count', this.property('tabs_count') - 1, false);
		},

		onTabClick: function(event) {
			var $tab = $(event.currentTarget);
			var contentId;

			// And make tab active
			$tab
				.siblings().removeClass('tabs-tab-active').end()
				.addClass('tabs-tab-active');
			$('#' + $tab.data('content-id'))
				.siblings().removeClass('utab-content-active').end()
				.addClass('utab-content-active');

			if (Upfront.Application.user_can_modify_layout()) {
				// Stop tab content editor on switching tabs, always
				this.$el.find('.utab-content').each(function () {
					var ed = $(this).data('ueditor');
					if(ed && ed.active) {
						ed.stop();
					}
				});

				// Otherwise stop all tab editors just in case
				this.$el.find('.tabs-tab:not(.tabs-tab-active) .inner-box').each(function() {
					var ed = $(this).data('ueditor');
					if(ed && ed.active) {
						$(this).trigger('blur');
					}
				});
			}
		},

		saveTabContent: function($content) {
			if (!Upfront.Application.user_can_modify_layout()) return false;

			var
				tabId = $content.attr('id').split('-').pop(),
				ed = $content.data('ueditor'),
				text = '';

			try {
				text = ed.getValue(true);
			} catch (e) {
				text = $content.html();
			}
			this.currentTabId = $content.attr('id');
			this.property('tabs')[tabId].content = text;
			this.render();
		},

		stopEdit: function(event) {
			var $content = this.$el.find('.utab-content-active'),
				ed = $content.data('ueditor');

			if (ed && ed.active) {
				ed.stop();
			}

			if(typeof event !== 'undefined' && $(event.target).hasClass('inner-box')) {
				return;
			}


			var $tab = this.$el.find('.tabs-tab-active .inner-box:not(.ueditor-placeholder)');
			$tab.trigger('blur');
		},

		onTabKeydown: function(event) {
			var id;
			if (event.key === 13) {
				event.preventDefault();
				$(event.currentTarget).removeAttr('contenteditable');
				id = $(event.currentTarget).data('content-id').split('-').pop();
				this.property('tabs')[id].title = $(event.currentTarget).text();
				this.addTooltips();
				if ($(event.currentTarget).find('i').length < 1) {
					$(event.currentTarget).append('<i></i>');
				}
			}
		},

		get_content_markup: function () {
			var props = this.extract_properties();

			props.show_add = true;
			props.show_remove = this.property('tabs_count') > 1 ? true : false;
			props.preset = props.preset || 'default';

			return this.tabsTpl(props);
		},

		extract_properties: function() {
			var props = {};
			this.model.get('properties').each(function(prop){
				props[prop.get('name')] = prop.get('value');
			});
			return props;
		},

		on_render: function() {
			// Tabs won't be rendered in time if no delay.
			_.delay(function(self) {
				self.addTooltips();
			}, 10, this);

			var me = this,
				$tabtitles = this.$el.find('.tabs-tab .inner-box'),
				count = 0,
				$tabs;

			if (Upfront.Application.user_can_modify_layout()) {
				me.initializeTabTitleEditor($tabtitles);
			} else {
				this.$el.find('.tabs-tab i').remove();
			}

			if (Upfront.Application.user_can_modify_layout()) {
				$tabs = this.$el.find('.utab-content');

				$tabs.each(function () {
					me.initializeContentEditor($(this));
				});
			}

			var $upfrontObjectContent = this.$el.find('.upfront-object-content');
			// if(this.$el.find('a.add-item').length < 1) {
			// 	$('<b class="upfront-entity_meta upfront-ui add_item"><a href="" class="upfront-icon-button add-item"></a></b>').insertBefore($upfrontObjectContent);
			// }

			this.$el.find('div#'+ this.currentTabId).addClass('utab-content-active').siblings().removeClass('utab-content-active');

			this.$el.find('.tabs-tab').removeClass('tabs-tab-active');
			this.$el.find('div.tabs-tab[data-content-id="' + this.$el.find('div.utab-content-active').attr('id')+'"]').addClass('tabs-tab-active');

			Upfront.Events.trigger('entity:object:refresh', this);
		},

		initializeTabTitleEditor: function($tabtitles) {
			var me = this,
				count = 0
			;
			$tabtitles.each(function () {
				var $content = $(this);
				count++;

				$content.ueditor({
					linebreaks: false,
					disableLineBreak: true,
					placeholder: false,
					air: false,
					autostart: false,
					focus: false
				}).on('start', function() {
					Upfront.Events.trigger('upfront:element:edit:start', 'text');
					$(this).focus();
				}).on('stop', function () {
					var id = $content.parent().parent().data('content-id').split('-').pop();
					var editor = $content.data('ueditor');
					if (editor.getValue(true).trim() === '') {
					 me.property('tabs')[id].title =  l10n.tab_label + ' ' + count;
					 setTimeout( function() {
						 $content.text(l10n.tab_label + ' ' + count);
					 }, 50);
					} else {
					 me.property('tabs')[id].title =  editor.getValue(true).trim().replace(/<p.*?>/, '').replace('</p>', '');
					}
					Upfront.Events.trigger('upfront:element:edit:stop');
					me.currentTabId = $content.closest('.tabs-tab-active').data('content-id');
					me.render();
				}).on('keydown', function(e){
					if ( 9 === e.which || 13 === e.which ) {
						e.preventDefault();
						e.stopImmediatePropagation();
						return false;
					}
				});
			});
		},

		startContentEditor: function(event) {
			if (!Upfront.Application.user_can_modify_layout()) return false;
			var ed = $(event.currentTarget).data('ueditor');
			if( ed && !ed.active ) ed.start();
		},

		initializeContentEditor: function($content) {
			if (!Upfront.Application.user_can_modify_layout()) return false;
			var me = this;

			$content.ueditor({
				linebreaks: false,
				autostart: false,
				paragraphize: false,
				focus: false,
				placeholder: false
			})
			.on('start', function () {
				Upfront.Events.trigger('upfront:element:edit:start', 'text');
			})
			.on('stop', function () {
				me.stopContentEdit($content);
			});
		},

		stopContentEdit: function($content) {
			if (!Upfront.Application.user_can_modify_layout()) return false;

			if($content.text().trim() === '') {
				$content.html(l10n.tab_placeholder);
			}
			this.saveTabContent($content);
			Upfront.Events.trigger('upfront:element:edit:stop');
		},

		addTooltips: function() {
			$('.tabs-tab').each(function() {
				var span = $(this).find('span')[0];
				if ( !_.isUndefined(span) && ( span.offsetWidth < span.scrollWidth ) ) {
					$(this).attr('title', $(span).text().trim());
				}
			});
		},

		property: function(name, value, silent) {
			if(typeof value !== 'undefined'){
				if(typeof silent === 'undefined') {
					silent = true;
				}
				return this.model.set_property(name, value, silent);
			}
			return this.model.get_property_value_by_name(name);
		},

		getControlItems: function(){
			return _([
				this.createControl('add', l10n.add_tab, 'addTab'),
				this.createPaddingControl(),
				this.createControl('settings', l10n.settings, 'on_settings_click')
			]);
		}
	});

	Upfront.Application.LayoutEditor.add_object('Utabs', {
		'Model': UtabsModel,
		'View': UtabsView,
		'Element': TabsElement,
		'Settings': TabsSettings,
		'anchor': {
			is_target: false
		},
		cssSelectors: {
			'.upfront-tabs-container': {label: l10n.css.container_label, info: l10n.css.container_info},
			'.upfront-tabs-container .tabs-menu-wrapper': {label: l10n.css.menu_label, info: l10n.css.menu_info},
			'.upfront-tabs-container .tabs-tab .inner-box': {label: l10n.css.tabs_label, info: l10n.css.tabs_info},
			'.upfront-tabs-container .tabs-tab-active .inner-box' : {label: l10n.css.active_tab_label, info: l10n.css.active_tab_info},
			'.upfront-tabs-container .utabs-content': {label: l10n.css.tab_content_label, info: l10n.css.tab_content_info},
			'.upfront-tabs-container .utabs-content p': {label: l10n.css.tab_p_label, info: l10n.css.tab_p_info},
			'.upfront-tabs-container .utab-content-active': {label: l10n.css.active_content_label, info: l10n.css.active_content_info},
			'.upfront-tabs-container .utab-content-active p': {label: l10n.css.active_p_label, info: l10n.css.active_p_info}
		},
		cssSelectorsId: Upfront.data.utabs.defaults.type
	});

	Upfront.Models.UtabsModel = UtabsModel;
	Upfront.Views.UtabsView = UtabsView;

});
})(jQuery);


upfrontrjs.define('text!elements/upfront-this-post/tpl/preset-style.html',[],function () { return '<?php if(!empty($properties[\'preset_style\'])) { ?><?php echo $properties[\'preset_style\'] ?><?php } ?>\r\n';});

(function ($) {
upfrontrjs.define('this_post',[
	'scripts/upfront/element-settings/settings',
	'scripts/upfront/element-settings/root-settings-panel',
	'scripts/upfront/preset-settings/util',
	'text!elements/upfront-this-post/tpl/preset-style.html'
], function(ElementSettings, RootSettingsPanel, Util, styleTpl) {

var l10n = Upfront.Settings.l10n.this_post_element;

/**
 * Define the model - initialize properties to their default values.
 * @type {Upfront.Models.ObjectModel}
 */
var ThisPostModel = Upfront.Models.ObjectModel.extend({
	/**
	 * The init function is called after the contructor and Model intialize.
	 * Here the default values for the model properties are set.
	 */
	init: function () {
		var properties = _.clone(Upfront.data.thisPost.defaults);
		properties.element_id = Upfront.Util.get_unique_id(properties.id_slug + '-object');
		this.init_properties(properties);
	}
});

var ThisPostView = Upfront.Views.ObjectView.extend({
	changed: false,
	markup: false,
	loading: false,
	postId: false,
	editor: false,

	initialize: function(options){
		var me = this;
		if(! (this.model instanceof ThisPostModel)){
			this.model = new ThisPostModel({properties: this.model.get('properties')});
		}
		this.listenTo(this.model.get('properties'), 'change', this.reset_markup);
		this.constructor.__super__.initialize.call(this, [options]);

		if (Upfront.Application.mode.current === Upfront.Application.MODE.THEME) {
			// Only extend events with post layout editing in theme editing mode
			_.extend(this.events, {
				'click .upfront-post-layout-trigger': 'editPostLayout'
			});
		}
		this.delegateEvents();

		this.postId = _upfront_post_data.post_id ? _upfront_post_data.post_id : Upfront.Settings.LayoutEditor.newpostType ? 0 : false;

		if(this.postId){
			this.refreshMarkup().then(function(){
				if(me.postId)
					me.prepareEditor();
			});
			//let's also start the editor before getting the markup
			//so its load will be faster
			me.prepareEditor();
		} else if ("themeExporter" in Upfront && Upfront.Application.mode.current === Upfront.Application.MODE.THEME) {
			// We're dealing with a theme exporter request
			// Okay, so let's fake a post
			this.postId = "fake_post";
			this.refreshMarkup();
			me.prepareEditor();
		}else if("themeExporter" in Upfront && Upfront.Application.mode.current === Upfront.Application.MODE.CONTENT_STYLE ){
            this.postId = "fake_styled_post";
            this.refreshMarkup();
            me.prepareEditor();
        }

		this.listenToOnce(this, 'rendered', function(){
			if( window.location.pathname.indexOf('/edit/') !== -1 )
			me.editor.loadingLayout.done(function() {
				setTimeout(function() {
					//Upfront.Events.trigger('post:layout:edit', me, 'archive');
					me.editor.editContents();
				}, 200);

			});
		});

		Upfront.Events.trigger('post:initialized', this);
	},

	/**
	 * Element contents markup.
	 * @return {string} Markup to be shown.
	 */
	get_content_markup: function () {
		if(!this.markup){
			this.refreshMarkup();
			return 'loading';
		}
		return this.markup;
	},

	reset_markup: function () {
		var me = this,
			props = ['hide_featured_image', 'full_featured_image'];
		if ( ! this.markup )
			return;
		_.find(props, function(prop){
			var value = me.property(prop),
				prev_value = me._properties[prop];
			if ( !value && !prev_value ) // nothing change
				return false;
			if ( prev_value != value ){
				me.markup = false;
				return true;
			}
			return false;
		});
		if ( this.markup === false && this.editor ){ // Markup refreshed, let's also fetchPostLayout
			this.editor.fetchPostLayout();
		}
	},

	prepareEditor: function(){
		var node = this.$('.upfront-object-content').children();

		//If we don't have the node rendered yet,
		//start the editor in a separated div
		if(!node.length)
			node = [$('<div>')];

		if(!this.editor){
			this.editor = new Upfront.Content.PostEditorLegacy({
				editor_id: 'this_post_' + this.postId,
				post_id: this.postId,
				preload: true,
				node: node[0],
				content_mode: 'post_content',
				view: this,
				layout: this.property('layout')
			});
			this.editor.render();
		}
		else
			this.editor.setElement(node[0]);
	},

	on_render: function(){
		if(!this.editor)
			return;

		var me = this,
			contents = this.$('.upfront-object-content').children()
		;

		// Always allow this_post to be deleted
		// Since we have new single post data element already
		if ( this.parent_module_view.model.get_property_value_by_name('sticky') ) {
			this.parent_module_view.model.set_property('sticky', false);
			// Add the button manually
			this.parent_module_view.$el.find('> .upfront-module > .upfront-entity_meta').prepend('<a href="#" class="upfront-icon-button upfront-icon-button-delete upfront-entity-delete_trigger"></a>');
		}

		// Make sure we have an element to swap with, first up
		if(contents[0] && contents[0] != this.editor.el){
			this.editor.setElement( contents[0] );
			this.editor.render(); // ... and don't forget to re-render when swapping els
		}

		// Let's not render min-height (remove it)
		this.$el.find('> .upfront-object').css('min-height', '');
		this.parent_module_view.$el.find('> .upfront-module').css('min-height', '');
		this.add_region_class('upfront-region-container-has-this_post', true);

		//this.editor.render();
		this.trigger('rendered');
	},

	//get_buttons: function(){
	//	return '<a href="#" class="upfront-icon-button upfront-icon-button-nav upfront-post-layout-trigger"></a>';
	//},
    get_extra_buttons: function(){
        return Upfront.Application.mode.current === Upfront.Application.MODE.THEME
        	? '<a href="#" title="Edit post layout" class="upfront-icon-button upfront-icon-button-nav upfront-post-layout-trigger"></a>'
        	: ''
        ;
    },
	on_edit: function (e) {
		if(!this.editor){
			this.prepareEditor();
		}
	},

	editPostLayout: function(){
		this.markup = false;
		Upfront.Events.trigger('post:layout:edit', this, 'single');
	},

    editPostContent: function(){
        this.editor.editContents();
        //Upfront.Events.trigger('upfront:element:edit:start', 'write', this);
    },

	refreshMarkup: function () {
		var me = this;

		if(this.loadingMarkup)
			return this.loadingMarkup;

		if(this.postId === false)
			return new $.Deferred().resolve({data:{filtered: 'Error'}});

		var node = $('#' + me.property('element_id')).find(".upfront-object-content"),
			loading = !node.length ? false : new Upfront.Views.Editor.Loading({
				loading: l10n.refreshing,
				done: l10n.here_we_are,
				fixed: false
			})
		;

		if(loading){
			loading.render();
			node.append(loading.$el);
		}

		this._properties = {
			post_data: this.property("post_data"),
			element_id: this.property('element_id'),
			hide_featured_image: this.property('hide_featured_image'),
			full_featured_image: this.property('full_featured_image')
		};

		this.loadingMarkup = Upfront.Util.post({
				action: "this_post-get_markup",
				data: JSON.stringify({
					post_id: this.postId,
					post_type: Upfront.Settings.LayoutEditor.newpostType,
					properties: this._properties
				})
			}).done(function(response){
				if(loading){
					loading.done();
					loading = false;
				}
				var node = node || $('#' + me.property('element_id')).find(".upfront-object-content");
				me.markup = response.data.filtered;
				node.html(me.get_content_markup());

				me.on_render();

				me.loadingMarkup = false;
			})
		;

		return this.loadingMarkup;
	},

	redirectPostEdit: function (post) {
		//window.location = Upfront.Settings.Content.edit.post + post.id;
		var path = '/edit/' + post.get('post_type') + '/' + post.id;
		if(_upfront_post_data) _upfront_post_data.post_id = post.id;
		Upfront.Application.navigate(path, {trigger: true});
		if (Upfront.Application.user_can("EDIT"))
			Upfront.Application.set_current(Upfront.Settings.Application.MODE.LAYOUT);
	},

	createEditor: function(node){
		var me = this;

		if(this.editor)
			return;

		this.editor = new Upfront.Content.editor({
			editor_id: 'this_post_' + this.postId,
			post_id: this.postId,
			preload: true,
			node: node,
			content_mode: 'post_content',
			view: me,
			autostart: this.autostart,
			onUpdated: function(post){
				me.autostart = false;
				me.editor.autostart = false;
				me.refreshMarkup(post);
				me.trigger('post:updated', post);
			}
		});

		this.listenTo(this.editor, 'editor:cancel', function(){
			me.editor.autostart = false;
			me.editor.initEditAreas();
		});
	},

	on_element_edit_start: function (edit, post) {
		if ( edit == 'write' && this.parent_module_view){
			if ( post.id != this.postId )
				this.parent_module_view.disable_interaction(false);
			else
				this.parent_module_view.$el.find('.upfront-module').addClass('upfront-module-editing');
		}
	},

	on_element_edit_stop: function (edit, post, saving_draft) {
		if(this.parent_module_view && saving_draft !== true){
			this.parent_module_view.$el.find('.upfront-module').removeClass('upfront-module-editing');
			this.parent_module_view.enable_interaction(false);
		}
	},

	/*
	Shorcut to set and get model's properties.
	*/
	property: function(name, value, silent) {
		if(typeof value != "undefined"){
			if(typeof silent == "undefined")
				silent = true;
			return this.model.set_property(name, value, silent);
		}
		return this.model.get_property_value_by_name(name);
	},

	cleanup: function(){
		if(this.editor){
			this.editor.remove();
			this.editor = false;
		}
		this.remove_region_class('upfront-region-container-has-this_post', true);
	}
});

/**
 * Editor command class - this will be injected into commands
 * and allow adding the new entity instance to the work area.
 * @type {Upfront.Views.Editor.Command}
 */
var ThisPostElement = Upfront.Views.Editor.Sidebar.Element.extend({

	draggable: false,

	/**
	 * Set up command appearance.
	 */
	render: function () {
		this.$el.html(l10n.element_name);
	},

	/**
	 * What happens when user clicks the command?
	 * We're instantiating a module with search entity (object), and add it to the workspace.
	 */
	add_element: function () {
		var object = new ThisPostModel(), // Instantiate the model
			// Since search entity is an object,
			// we don't need a specific module instance -
			// we're wrapping the search entity in
			// an anonymous general-purpose module
			module = new Upfront.Models.Module({
				"name": "",
				"properties": [
					{"name": "element_id", "value": Upfront.Util.get_unique_id("module")},
					{"name": "class", "value": "c6 upfront-this_post_module"},
					{"name": "has_settings", "value": 0},
					{"name": "row", "value": 20}
				],
				"objects": [
					object // The anonymous module will contain our search object model
				]
			})
		;
		// We instantiated the module, add it to the workspace
		this.add_module(module);
	}
});

var Settings_PostPanel_PostData = Upfront.Views.Editor.Settings.Item.extend({
	initialize: function (opts) {
		this.options = opts;
		var data = [
			{label: l10n.post_author, value: "author"},
			{label: l10n.post_date, value: "date"},
			{label: l10n.categories, value: "categories"},
			{label: l10n.tags, value: "tags"},
			{label: l10n.comments_count, value: "comments_count"},
			{label: l10n.featured_image, value: "featured_image"}
		];
		this.fields = _([
			new Upfront.Views.Editor.Field.Checkboxes({
				model: this.model,
				label: l10n.show_post_data,
				property: "post_data",
				values: data
			})
		]);
	},
	get_title: function () {
		return l10n.post_data;
	}
});

var Settings_PostPanel = RootSettingsPanel.extend({
	label: l10n.element_name,
	settings: [
		{
			type: 'SettingsItem',
			title: l10n.featured_image_option,
			fields: [
				{
					type: 'Checkboxes',
					property: "hide_featured_image",
					multiple: false,
					values: [{ label: l10n.hide_featured_image, value: '1' }],
					change: function (value, me) {
						if (value === '1')
							me.model.set_property('hide_featured_image', 1);
						else
							me.model.set_property('hide_featured_image', false);
					}
				},
				{
					type: 'Checkboxes',
					property: "full_featured_image",
					multiple: false,
					values: [{ label: l10n.full_featured_image, value: '1' }],
					change: function (value, me) {
						if (value === '1')
							me.model.set_property('full_featured_image', 1);
						else
							me.model.set_property('full_featured_image', false);
					}
				}
			]
		}
	],
	title: l10n.post_settings
});

var Settings = ElementSettings.extend({
	panels: {
		General: Settings_PostPanel,
		Appearance: {
			mainDataCollection: 'thispostPresets',
			styleElementPrefix: 'thispost-preset',
			ajaxActionSlug: 'thispost',
			panelTitle: l10n.settings,
			presetDefaults: Upfront.mainData.presetDefaults.thispost,
			styleTpl: styleTpl
		}
	},

	initialize: function (opts) {
		//If editor show only general preset
		if (location.pathname.indexOf('create_new') === -1) {// you are in exporter
			this.panels = { General: Settings_PostPanel };
		}

		// Call the super constructor here, so that the appearance panel is instantiated
		this.constructor.__super__.initialize.call(this, opts);
	},

	title: l10n.post_settings
});

// Generate presets styles to page
Util.generatePresetsToPage('thispost', styleTpl);

// ----- Bringing everything together -----
// The definitions part is over.
// Now, to tie it all up and expose to the Subapplication.
Upfront.Application.LayoutEditor.add_object("ThisPost", {
	Model: ThisPostModel,
	View: ThisPostView,
	Element: ThisPostElement,
	Settings: Settings
});
Upfront.Models.ThisPostModel = ThisPostModel;
Upfront.Views.ThisPostView = ThisPostView;

Upfront.data.thisPost.PostDataPanel = Settings_PostPanel;


});
})(jQuery);


upfrontrjs.define('text!elements/upfront-post-data/tpl/views.html',[],function () { return '<div id="post-data">\r\n\t<div class="post-data-wrapper">{{post_data}}</div>\r\n</div>\r\n\r\n<div id="loading">\r\n\t<p class="loading">{{l10n.loading}}</p>\r\n</div>\r\n\r\n\r\n<div id="error">\r\n\t<p class="error">{{l10n.error}}</p>\r\n</div>\r\n\r\n\r\n<div id="part-options-part_visible">\r\n\t<div class="name_action_wrapper"></div>\r\n</div>\r\n<div id="part-options-part_label">\r\n\t<span class="part_label"></span>\r\n</div>\r\n<div id="part-options-part_action">\r\n\t<span class="part_action"><a href="#edit-options">{{l10n.edit}}</a></span>\r\n</div>\r\n<div id="part-options-part_wrapper">\r\n\t<div class="options {{part.part}}-options">\r\n\t\t<div class="option"></div>\r\n\t\t<span class="edit_part"><a href="#edit-html">{{l10n.edit_html}}</a></span>\r\n\t</div>\r\n</div>';});

(function ($) {
upfrontrjs.define('elements/upfront-post-data/js/post-data-views',[
	'text!elements/upfront-post-data/tpl/views.html'
], function(tpl) {

var l10n = Upfront.Settings.l10n.post_data_element;
var $template = $(tpl);

var Util = {
	/**
	 * Gets the current preset data from in-memory collection
	 *
	 * Used instead of the stored preset on server
	 *
	 * @param {String} element Element type
	 * @param {String} preset_id Preset ID
	 *
	 * @return {Object} Local preset data
	 */
	get_preset_data: function (element, preset_id) {
		var data = {};
		if (!element || !preset_id) return data;

		var prefix = element + '_elementPresets',
			all = (Upfront.mainData || {})[prefix] || []
		;
		return _.findWhere(all, {id: preset_id}) || data;
	}
};

var Views = {

	DEFAULT: 'post_data',

	_view: Backbone.View.extend({
		_do_cache: true,

		render: function (only_objects) {
			var me = this,
				model = Upfront.Util.model_to_json(this.model),
				props = model.properties || {},
				objects = model.objects || {},
				data_type = this.model.get_property_value_by_name("data_type"),
				current_preset = this.model.get_property_value_by_name("preset"),
				preset_data = Util.get_preset_data(data_type, current_preset),
				data = {
					props: props,
					objects: objects,
					preset_data: preset_data,
					post_id: this.element.postId
				}
			;

			var pluginLayout = Upfront.Application.is_plugin_layout(data.post_id);
			if (pluginLayout)  {
				var showContent;
				var title = pluginLayout.title;
				var showTitle;
				this.model.get('objects').each(function(object) {
					if (object.get_property_value_by_name('part_type') === 'content') showContent = true;
					if (title && object.get_property_value_by_name('part_type') === 'title') showTitle = true;
				});
				if (showTitle) {
					title = '<div class="upostdata-part title"><h1>' + title + '</h1></div>';
					setTimeout( function() {
						me.element.$el.find('.part-title .upfront-object-content').first().empty().append(title);
					}, 100);
				}
				if (showContent) {
					var content = '<div>Below is sample content for ' + pluginLayout.pluginName + '. Use it as a reference for styling.</div>' + pluginLayout.content;
					// For some reason this.$el is not working when Settings are opened and canceled, use me.element instead
					setTimeout( function() {
						me.element.$el.find('.part-content .upfront-object-content').first().empty().append(content);
					}, 100);
				}
				return;
			}

			if (false === data.post_id && Upfront.Application.is_builder) {
				data.post_id = 'fake_post';
			}

			if ( this.element.authorId ) {
				data.author_id = this.element.authorId;
			}
			if ( this.element.postDate ) {
				data.post_date = this.element.postDate;
			}
			if ( data_type == 'featured_image' && this.element.full_featured_image ) {
				data.selected_featured_image = this.element.full_featured_image;
			}
			if ( data_type == 'post_data' && this.element.set_post_title ) {
				data.set_post_title = this.element.set_post_title;
			}
			if ( data_type == 'post_data' && this.element.set_post_content ) {
				data.set_post_content = this.element.set_post_content;
			}

			// Let's notify all part views that we are currently loading
			// This will disable editing until all part views is updated
			this.element.toggle_child_objects_loading(true);

			this._post_data_load = Upfront.Util
				.post({
					action: "upfront_post-data-load",
					data: data
				})
				.done(function (response) {
					if (response.data && response.data.post_data) {
						me.render_object_view(response.data.post_data, only_objects);
						if ( me._do_cache ) {
							me._cached_data = response.data.post_data;
						}
						me.$el
							.empty()
							.removeClass('upfront_post-data-loading');
					}
					else {
						me.$el
							.empty()
							.append(me.tpl.fail({l10n: l10n}))
							.removeClass('upfront_post-data-loading');
					}
					// Notify all part views that we have finished loading
					me.element.toggle_child_objects_loading(false);                    
				})
				.fail(function () {
					me.$el
						.empty()
						.append(me.tpl.fail({l10n: l10n}))
						.removeClass('upfront_post-data-loading');
					// Notify all part views that we have finished loading
					me.element.toggle_child_objects_loading(false);
				})
			;
			this.$el
				.empty()
				.append(this.tpl.load({l10n: l10n}))
				.addClass('upfront_post-data-loading');
		},

		/**
		 * Re-render with the same cached data
		 * @param {Array} only_objects
		 */
		rerender: function (only_objects) {
			if ( this._cached_data ) {
				this.render_object_view(this._cached_data, only_objects);
			}
			else {
				this.render();
			}
		},

		/**
		 * Render the child object view
		 * @param {Object} data
		 * @param {Array} only_objects
		 */
		render_object_view: function (data, only_objects) {
			if ( ! _.isArray(only_objects) ) only_objects = [];
			var me = this;
			this.model.get('objects').each(function(object){
				var view = Upfront.data.object_views[object.cid],
					type = object.get_property_value_by_name('part_type')
				;
				if ( only_objects.length > 0 && ! _.contains(only_objects, type) ) return;
				if ( !view || !type || !data[type] ) return;
				view.render_view(data[type]);
				Upfront.Events.trigger('entity:object:refresh', view);
			});
            
            // Hustle compatibility
            if ( typeof Hustle !== 'undefined' && typeof Hustle.Events !== 'undefined' ) {
                Hustle.Events.trigger('upfront:editor:shortcode:render', this);
            }
		},

		tpl: {
			main: _.template($template.filter("#post-data").html()),
			error: _.template($template.filter("#error").html()),
			load: _.template($template.filter("#loading").html())
		}
	})

};

Views.post_data = Views._view.extend({
	className: 'upfront_post-data-view upfront_post-data-post_data'
});

Views.author = Views._view.extend({
	className: 'upfront_post-data-view upfront_post-data-author'
});

Views.taxonomy = Views._view.extend({
	className: 'upfront_post-data-view upfront_post-data-taxonomy'
});

Views.featured_image = Views._view.extend({
	className: 'upfront_post-data-view upfront_post-data-featured_image'
});

Views.comments = Views._view.extend({
	className: 'upfront_post-data-view upfront_post-data-comments'
});

Views.meta = Views._view.extend({
	className: 'upfront_post-data-view upfront_post-data-meta'
});

return Views;

});
})(jQuery);

upfrontrjs.define('elements/upfront-post-data/js/panel-abstractions',[
	'scripts/upfront/settings/modules/base-module',
	'scripts/upfront/settings/field-factory',
	'scripts/upfront/preset-settings/state-settings',

	'scripts/redactor/ueditor-inserts',
	/**
	 * @todo Refactor this to a different, shared location
	 */
	'elements/upfront-posts/js/post-list-meta-views'
], function (BaseModule, FieldFactory, StateSettings, Inserts, Meta) {

	var l10n = Upfront.Settings.l10n.post_data_element;

	var OptionsModule = BaseModule.extend({
		className: function () {
			var cls = (typeof this.initialize === typeof BaseModule.prototype.className
				? BaseModule.prototype.className()
				: (BaseModule.prototype.className || '')
			).split(' ');
			cls.push('upfront-post_data-part');
			cls.push('part-module-panel');
			return cls.join(' ');
		},
		map_panel_fields: function () {
			var me = this,
				fields = this.get_fields(),
				object_model = new Upfront.Models.ObjectModel()
			;

			fields.push({
				type: "Button",
				label: l10n.custom_markup,
				className: 'edit_preset_label',
				compact: true
			});

			fields.push({
				type: "Button",
				label: l10n.edit_template,
				className: 'edit_post_markup edit_preset_css sidebar-commands-small-button',
				compact: true,
				on_click: function () {
					me.spawn_editor();
				}
			});

			_(this.model.attributes).each(function (value, key) {
				if ("id" === key || "name" === key) return true;
				object_model.set_property(key, value);
			});

			return _.map(fields, function (field) {
				var options = _.extend(field, {change: function (value) {
					me.update_object(value, field.property);
				}});
				return FieldFactory.createField(field.type, _.extend({ model: object_model }, _.omit(field, ['type'])));
			});
		},
		get_fields: function () { return []; },
		get_object_model: function () {
			return this.model;
		},
		update_object: function (value, property) {
			if (_.isUndefined(value) ) value = '';
			this.model.set(property, value);
			this.trigger("part:property:change", property, value);
		},
		render: function () {
			this.fields = _(this.map_panel_fields());
			this.options.title = this.title;
			BaseModule.prototype.render.apply(this, arguments);

			var modules = this.get_modules();

			this.state = new StateSettings({
				model: this.model,
				state: 'static',
				modules: modules
			});
			this.state.render();

			this.$el.append(this.state.$el);

			//Move Edit Preset to bottom
			this.$el.find('.state_modules').append(this.$el.find('.edit_preset_css'));
			this.$el.addClass("preset_specific");
		},
		get_modules: function () {
			var me = this,
				name = function (name) { return 'static-' + me.data_part + '-' + name; }
			;
			return [{
				moduleType: 'Typography',
				options: {
					toggle: true,
					state: 'static',
					fields: {
						use: name('use-typography'),
						typeface: name('font-family'),
						weight: name('weight'),
						fontstyle: name('fontstyle'),
						style: name('style'),
						size: name('font-size'),
						line_height: name('line-height'),
						color: name('font-color')
					}
				}
			}];
		},
		spawn_editor: function () {
			var me = this,
				tpl_name = 'post-part-' + this.data_part,
				template = this.model.get(tpl_name),
				embed_object = ('meta' === this.data_part ? Meta.Embed : Inserts.inserts.embed),
				editor = new embed_object({data: {code: template}, model: this.model}),
				manager = false,
				resize_cbk = function () {
					if (manager) {
						var width = jQuery('#sidebar-ui').width() - 1;
						manager.$el
							.width(jQuery(window).width() -  width)
							.css('left', width);
					}
				}
			;

			jQuery(window).on('resize', resize_cbk);

			editor
				.start()
				.done(function (view, code) {
					jQuery(window).off('resize', resize_cbk);
					me.model.set(tpl_name, code);
				})
			;

			// Temporarily hack size
			this.listenTo(editor, 'manager:rendered', function (mgr, main) {
				manager = mgr;
				resize_cbk();
			});
		},
		// These two just satisfy the interface
		get_name: function () { return false; },
		get_value: function () { return false; }
	});

	var ToggleableOptions = OptionsModule.extend({
		events: function () {
			return _.extend({}, OptionsModule.prototype.events, {
				'click .upfront-settings-item-title .toggle': 'toggle_box'
			});
		},
		render: function () {
			var me = this,
				value = { label: this.title, value: '1' },
				hidden_parts = this.model.get("hidden_parts") || [],
				is_hidden = true,
				check = false
			;

			if (hidden_parts.indexOf(me.data_part) < 0) {
				value["checked"] = "checked";
				is_hidden = false;
			}

			check = new Upfront.Views.Editor.Field.Checkboxes({
				default_value: 1,
				values: [value],
				change: function (value) {
					var hidden_parts = me.model.get("hidden_parts") || [],
						pos = hidden_parts.indexOf(me.data_part)
					;

					// Set up parts
					if (value && value.length && pos >= 0) {
						hidden_parts.splice(pos, 1);
					} else if (pos < 0) {
						hidden_parts.push(me.data_part);
					}
					me.model.set("hidden_parts", hidden_parts);

					// Set up appearances
					if (value && value.length) {
						me.$el.find(".upfront-settings-item-title").removeClass("inactive");
						me.show_content();
					} else {
						me.$el.find(".upfront-settings-item-title").addClass("inactive");
						me.hide_content();
					}

					// Do other stuff
					me.trigger("part:hide:toggle", me.data_part, (value && value.length && pos >= 0));
				}
			});
			check.render();
			check.delegateEvents();

			OptionsModule.prototype.render.apply(this, arguments);

			this.$el.find(".upfront-settings-item-title")
				.empty()
				.append(check.$el)
				.append('<a href="#toggle" class="toggle">&times;</a>')
			;

			// Hide the stuff that's meant to be hidden
			if (is_hidden) {
				this.hide_content();
			}

			// temporary style hack
			this.$el.find(".upfront-settings-item-title .toggle").css('background-image', 'url(' + Upfront.Settings.root_url.replace(/\/$/, '') + '/img/uf-ui-sprite.svg)');
		},
		toggle_box: function (e) {
			if (e && e.preventDefault) e.preventDefault();
			if (e && e.stopPropagation) e.stopPropagation();

			var $content = this.$el.find('.upfront-settings-item-content:first, .state_modules');
			if ($content.is(":visible")) this.hide_content();
			else this.show_content();

			return false;
		},
		hide_content: function () {
			var $content = this.$el.find('.upfront-settings-item-content:first, .state_modules');
			return $content.hide();
		},
		show_content: function () {
			var $content = this.$el.find('.upfront-settings-item-content:first, .state_modules');
			return $content.show();
		}
	});

	return {
		Options: OptionsModule,
		Toggleable: ToggleableOptions
	};
});


